"""TableTurn: a tiny table-turnover and waitlist tracker for small restaurants."""
from dataclasses import dataclass, field
from datetime import datetime, timedelta

@dataclass
class Table:
    number: int
    seats: int
    occupied_since: datetime | None = None

@dataclass
class Waitlist:
    entries: list = field(default_factory=list)

    def add(self, name: str, party: int):
        self.entries.append((name, party, datetime.now()))

    def next_fit(self, free_seats: int):
        for i, (name, party, _) in enumerate(self.entries):
            if party <= free_seats:
                return self.entries.pop(i)
        return None

def estimate_turn(tables: list[Table], avg_minutes: int = 60) -> list[tuple[int, datetime]]:
    out = []
    for t in tables:
        if t.occupied_since:
            out.append((t.number, t.occupied_since + timedelta(minutes=avg_minutes)))
    return out

if __name__ == "__main__":
    tables = [Table(1, 2), Table(2, 4), Table(3, 6, datetime.now())]
    wl = Waitlist()
    wl.add("Garcia", 4)
    wl.add("Chen", 2)
    print("Free seats at table 2 -> seats", tables[1].seats)
    print("Next fit:", wl.next_fit(4))
    print("Expected turns:", estimate_turn(tables))
EOF
